{"code": "
fen = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"

def evaluate(pos):
    if pos["game_over"]:
        w = pos.get("winner")
        if w == "white":
            return 100000
        elif w == "black":
            return -100000
        else:
            return 0
    sq = pos["squares"]
    vals = {'p':100,'n':320,'b':330,'r':500,'q':900,'k':0}
    score = 0
    for s, piece in sq.items():
        v = vals[piece.lower()]
        if piece.isupper():
            score += v
        else:
            score -= v
        # centralization
        if s in ('d4','e4','d5','e5'):
            if piece.isupper():
                score += 12
            else:
                score -= 12
    # check term
    if pos["in_check"]:
        side = pos["turn"]
        if side == "white":
            score -= 25
        else:
            score += 25
    return score

cands = sorted(simulate_move(fen, None)["legal_moves"])
best = None
best_score = None
for c in cands:
    after_white = simulate_move(fen, c)
    if after_white["game_over"]:
        cand_score = evaluate(after_white)
    else:
        replies = sorted(after_white["legal_moves"])
        cand_score = min(evaluate(simulate_move(after_white["fen"], r)) for r in replies)
    if best_score is None or cand_score > best_score:
        best_score = cand_score
        best = c
    print(c, cand_score)
print("BEST:", best, best_score)
play_move(best)
"}

